### Describe the bug

Setting:
```
quarkus.http.enable-compression=true
quarkus.http.compress-media-types=text/html,text/xml,text/plain,text/css,text/javascript,application/javascript,application/json,application/xml"
```

does not have any effect on 
```
    <servlet>
        <servlet-name>Faces Servlet</servlet-name>
        <servlet-class>jakarta.faces.webapp.FacesServlet</servlet-class>
    </servlet>
    <servlet-mapping>
        <servlet-name>Faces Servlet</servlet-name>
        <url-pattern>/</url-pattern>
    </servlet-mapping>
    <servlet-mapping>
        <servlet-name>Faces Servlet</servlet-name>
        <url-pattern>*.xhtml</url-pattern>
    </servlet-mapping>
```

using a own filter is a workaround - we can even reuse the quarkus settings:
```
package de.agoris.faces.framework;

import jakarta.servlet.Filter;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletOutputStream;
import jakarta.servlet.ServletRequest;
import jakarta.servlet.ServletResponse;
import jakarta.servlet.WriteListener;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpServletResponseWrapper;
import org.eclipse.microprofile.config.inject.ConfigProperty;

import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.List;
import java.util.zip.GZIPOutputStream;

public class CompressionFilter implements Filter {

    @ConfigProperty(name = "quarkus.http.enable-compression", defaultValue = "false")
    boolean compressionEnabled;

    @ConfigProperty(name = "quarkus.http.compress-media-types",
            defaultValue = "text/html,text/xml,text/plain,text/css,text/javascript,application/javascript,application/json,application/xml")
    List<String> compressMediaTypes;

    @ConfigProperty(name = "quarkus.http.compression-threshold", defaultValue = "1024")
    int compressionThreshold;

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {

        // Only proceed if compression is enabled
        if (!compressionEnabled) {
            chain.doFilter(request, response);
            return;
        }

        HttpServletRequest httpReq = (HttpServletRequest) request;
        HttpServletResponse httpResp = (HttpServletResponse) response;

        // Check if client supports gzip
        String acceptEncoding = httpReq.getHeader("Accept-Encoding");
        if (acceptEncoding == null || !acceptEncoding.contains("gzip")) {
            chain.doFilter(request, response);
            return;
        }

        // Create a wrapper to capture response data
        CompressionResponseWrapper wrappedResponse = new CompressionResponseWrapper(httpResp);

        try {
            // Process the request
            chain.doFilter(request, wrappedResponse);

            // Check if we should compress based on content type and size
            if (shouldCompress(wrappedResponse.getContentType(), wrappedResponse.getDataSize())) {
                // Set compression headers
                httpResp.setHeader("Content-Encoding", "gzip");
                httpResp.setHeader("Vary", "Accept-Encoding");

                // Compress and write the response
                try (GZIPOutputStream gzipOut = new GZIPOutputStream(httpResp.getOutputStream())) {
                    gzipOut.write(wrappedResponse.getData());
                }
            }
            else {
                // Write uncompressed response
                httpResp.getOutputStream().write(wrappedResponse.getData());
            }
        }
        finally {
            wrappedResponse.close();
        }
    }

    private boolean shouldCompress(String contentType, int dataSize) {
        // Check size threshold
        if (dataSize < compressionThreshold) {
            return false;
        }

        // Check content type
        if (contentType == null) {
            return false;
        }

        // Normalize content type (remove charset, etc.)
        String normalizedContentType = contentType.toLowerCase().split(";")[0].trim();

        return compressMediaTypes.stream().anyMatch(mediaType -> {
            String normalizedMediaType = mediaType.toLowerCase().trim();

            // Handle wildcards like "text/*"
            if (normalizedMediaType.endsWith("/*")) {
                String prefix = normalizedMediaType.substring(0, normalizedMediaType.length() - 2);
                return normalizedContentType.startsWith(prefix);
            }

            // Exact match
            return normalizedContentType.equals(normalizedMediaType);
        });
    }

    /**
     * Response wrapper that captures the response data for compression analysis
     */
    private static class CompressionResponseWrapper extends HttpServletResponseWrapper {
        private final ServletOutputStreamWrapper outputStreamWrapper;
        private PrintWriter writer;
        private boolean outputStreamUsed = false;
        private boolean writerUsed = false;

        public CompressionResponseWrapper(HttpServletResponse response) {
            super(response);
            this.outputStreamWrapper = new ServletOutputStreamWrapper();
        }

        @Override
        public ServletOutputStream getOutputStream() throws IOException {
            if (writerUsed) {
                throw new IllegalStateException("getWriter() has already been called");
            }
            outputStreamUsed = true;
            return outputStreamWrapper;
        }

        @Override
        public PrintWriter getWriter() throws IOException {
            if (outputStreamUsed) {
                throw new IllegalStateException("getOutputStream() has already been called");
            }
            if (writer == null) {
                writerUsed = true;
                String encoding = getCharacterEncoding();
                if (encoding == null) {
                    encoding = "UTF-8";
                }
                writer = new PrintWriter(new OutputStreamWriter(outputStreamWrapper, encoding));
            }
            return writer;
        }

        public byte[] getData() {
            if (writer != null) {
                writer.flush();
            }
            return outputStreamWrapper.getData();
        }

        public int getDataSize() {
            return getData().length;
        }

        public void close() throws IOException {
            if (writer != null) {
                writer.close();
            }
            outputStreamWrapper.close();
        }
    }

    /**
     * ServletOutputStream implementation that captures data to a byte array
     */
    private static class ServletOutputStreamWrapper extends ServletOutputStream {
        private final java.io.ByteArrayOutputStream buffer = new java.io.ByteArrayOutputStream();

        @Override
        public void write(int b) throws IOException {
            buffer.write(b);
        }

        @Override
        public void write(byte[] b, int off, int len) throws IOException {
            buffer.write(b, off, len);
        }

        @Override
        public boolean isReady() {
            return true;
        }

        @Override
        public void setWriteListener(WriteListener listener) {
            // No-op for this implementation
        }

        public byte[] getData() {
            return buffer.toByteArray();
        }

        public void close() throws IOException {
            buffer.close();
        }
    }
}
```

